// Prepare the request for Perplexity API
const webhookData = $input.first().json;

// Handle different webhook structures safely
const intention = webhookData.body?.intention || webhookData.query?.intention || webhookData.intention;

if (!intention) {
  throw new Error("No intention found in Webhook data");
}

const systemPrompt = `You are an elite industry researcher for 'SmallTalk'.
Your goal is to find SPECIFIC, TENSION-FILLED topics for a high-level professional conversation.

SEARCH GUIDELINES:
1. **FIND THE TENSION:** What is the specific controversy, regulation, or supply chain bottleneck affecting this role RIGHT NOW (late 2025/2026)?
2. **FIND THE GLIMMER:** What is one specific innovation or pilot program happening this month?
3. **SPECIFICITY IS KING:** Do not find "AI trends." Find "The debate over Open Source vs Closed Source LLMs in Enterprise Security."

OUTPUT REQUIREMENTS:
- Find 2 specific proper nouns (Companies, Acts, Bills, Technologies).
- Find 1 specific debate.`;

const userPrompt = `The user is in this situation:
"${intention}"

Research the specific industry context.
Find me the "Deep Cut" information—the stuff only insiders are talking about this week.
I need specific details to build a script that makes the user sound smart and well-read.`;

return {
  intention: intention,
  perplexity_request: {
    model: "sonar-pro",
    messages: [
      { role: "system", content: systemPrompt },
      { role: "user", content: userPrompt }
    ],
    temperature: 0.2,
    max_tokens: 2000,
    search_recency_filter: "month"
  }
};

// Handle Perplexity response and prepare Claude request
const input = $input.first().json;

// Get intention from previous node safely
let intention = "Professional Context";
try {
   intention = $("Prepare Perplexity Request").first().json.intention; 
} catch(e) {
   intention = input.intention || "Professional Context"; 
}

// Check Perplexity Success
if (!input.choices || !input.choices[0] || !input.choices[0].message) {
  return {
    success: false,
    error: "Perplexity API failed",
    intention: intention
  };
}

const researchData = input.choices[0].message.content;

// --- WINGMAN SYSTEM PROMPT ---
const systemPrompt = `You are Wingman - an AI communication partner that helps professionals nail high-stakes conversations.

Your job: Give them SPECIFIC, CURRENT scripts so they walk in confident, not anxious.

CRITICAL RULES:
1. NO PLACEHOLDERS - no [brackets], no generic advice. Use actual facts from the research.
2. NATURAL LENGTH - Write naturally. 1-3 sentences per card. Don't artificially compress.
3. NATURAL TONE - Sound like their smartest friend texting them right before the big moment. Confident but warm.
4. SPECIFICITY - Reference actual companies, stats, trends from the research. Generic = useless.
5. CONVERSATIONAL - Write like people actually talk. No corporate jargon.

CARD PURPOSES:
- Hook: An opening line or question to start conversation
- Anchor: A fact or insight to reference if conversation flows
- Exit: A graceful way to LEAVE that sets up FUTURE connection (must include action like "coffee", "follow up", "connect")
- Mantra: A grounding phrase for confidence

Return ONLY valid JSON (no markdown, no code fences).`;

const userPrompt = `Context: "${intention}"

RESEARCH DATA:
${researchData}

---

Create a SINGLE JSON object with 3 confidence card variations.

CRITICAL: Return ONE JSON object with this EXACT structure:
{
  "card1": {
    "hook": "...",
    "anchor": "...",
    "exit": "...",
    "mantra": "..."
  },
  "card2": {
    "hook": "...",
    "anchor": "...",
    "exit": "...",
    "mantra": "..."
  },
  "card3": {
    "hook": "...",
    "anchor": "...",
    "exit": "...",
    "mantra": "..."
  }
}

IMPORTANT: Be specific. Use natural language. Make sure Exit includes a future connection action.`;

// --- END WINGMAN PROMPT ---

return {
  success: true,
  intention: intention,
  claude_request: {
    model: "claude-sonnet-4-20250514", 
    max_tokens: 1500,
    system: systemPrompt,
    messages: [
      { role: "user", content: userPrompt }
    ]
  }
};

// Parse and validate Claude response
const input = $input.first().json;

// Safely get intention
let intention = "Unknown";
try {
    const prevNode = $("Process Research & Prepare Claude").first();
    if(prevNode) intention = prevNode.json.intention;
} catch(e) {}

// 1. Check Success
if (!input.content || !input.content[0] || !input.content[0].text) {
  return {
    success: false,
    error: "Claude API failed",
    error_details: JSON.stringify(input),
    intention: intention
  };
}

let text = input.content[0].text;

// 2. Clean markdown
text = text.replace(/```json/gi, "").replace(/```/g, "").trim();

try {
  // 3. Find the JSON object
  const firstBrace = text.indexOf('{');
  const lastBrace = text.lastIndexOf('}');

  if (firstBrace === -1 || lastBrace === -1) {
    throw new Error("No JSON found in response");
  }

  const jsonStr = text.substring(firstBrace, lastBrace + 1);
  const parsed = JSON.parse(jsonStr);

  // 4. Extract the 3 cards
  const cards = {
    card1: parsed.card1 || {},
    card2: parsed.card2 || {},
    card3: parsed.card3 || {}
  };

  // 5. Return all 3 cards
  return {
    success: true,
    intention: intention,
    data: cards
  };

} catch (error) {
  return {
    success: false,
    error: "JSON Parsing Failed",
    error_details: error.message,
    raw_response: text,
    intention: intention
  };
}
